se = fabs(p_b.m[0][1] - p_b.m[1][0]) + fabs(p_b.m[0][2] - p_b.m[2][0]) +
     fabs(p_b.m[1][2] - p_b.m[2][1]);

*trace = tr;
*symmetry_error = se;
return ADCS_OK;
